sp_widget.css:
/* ==========================================
   CARD
========================================== */

.tm-card{
    background:#FFFFFF;
    border:1px solid #E5E7EB;
    border-radius:16px;
    padding:18px;
    box-shadow:0 2px 8px rgba(15,23,42,.05);
}

/* ==========================================
   TITLE
========================================== */

.tm-card-title{
    margin:0 0 16px;
    font-size:16px;
    font-weight:600;
    color:#0F172A;
}

/* ==========================================
   ACTIONS
========================================== */

.tm-actions{
    display:flex;
    flex-direction:column;
    gap:10px;
}

/* ==========================================
   BUTTONS
========================================== */

.tm-action{
    display:flex;
    align-items:center;
    gap:10px;

    padding:12px 14px;

    border:1px solid #E5E7EB;

    border-radius:12px;

    background:#FFFFFF;

    color:#334155;

    font-size:13px;
    font-weight:600;

    text-decoration:none;

    transition:.2s;
}

.tm-action:hover{
    background:#F8FAFC;
    border-color:#CBD5E1;
    text-decoration:none;
    color:#0F172A;
}

/* ==========================================
   PRIMARY ACTION
========================================== */

.tm-action.primary{
    background:#2563EB;
    border-color:#2563EB;
    color:#FFFFFF;
}

.tm-action.primary:hover{
    background:#1D4ED8;
    border-color:#1D4ED8;
    color:#FFFFFF;
}

/* ==========================================
   ICONS
========================================== */

.tm-action i{
    width:18px;
    text-align:center;
    font-size:14px;
}

sp_widget.script:
(function() {

    data.canCreate = true;

    data.canPrescribe = true;

    data.canRefill = true;

})();
